Changed file: Sources/BeamfallKit/Models.swift

Intent:
feat(kit): decode ADR-0034 locale-map titles — resolve at decode time

The server now serves map-form display strings for translated titles
(first-party bundles carry fr). LocaleText decodes both wire forms —
plain shorthand and {tag: value} maps — resolving against the device
locale (exact tag → truncated tag → en → smallest tag), so
NavigationNode/Section titles stay plain String for every view.
Encoding still writes the resolved string (Snapshot persistence
stays plain text).

Co-Authored-By: Claude Fable 5 <noreply@anthropic.com>

Diff of the changed file:
@@ -42,6 +42,43 @@ public struct LibrarySummary: Codable, Equatable, Identifiable, Sendable {
     }
 }

+/// Decodes one display string off the wire (ADR-0034 locale maps): plain
+/// string shorthand (≡ `{en: …}`) or a full `{tag: value}` map, resolved at
+/// decode time against the device locale — exact tag, then progressively
+/// truncated (fr-CA → fr), then English, then the lexicographically smallest
+/// tag so malformed maps still render deterministically.
+public enum LocaleText {
+    public static func decode<K>(
+        in container: KeyedDecodingContainer<K>, forKey key: K
+    ) throws -> String {
+        if let plain = try? container.decode(String.self, forKey: key) {
+            return plain
+        }
+        let map = try container.decode([String: String].self, forKey: key)
+        return resolve(map, locale: Locale.current)
+    }
+
+    public static func resolve(_ map: [String: String], locale: Locale) -> String {
+        if map.isEmpty {
+            return ""
+        }
+        var tag = locale.identifier.replacingOccurrences(of: "_", with: "-").lowercased()
+        while !tag.isEmpty {
+            if let value = map[tag] {
+                return value
+            }
+            guard let cut = tag.lastIndex(of: "-") else {
+                break
+            }
+            tag = String(tag[..<cut])
+        }
+        if let english = map["en"] {
+            return english
+        }
+        return map[map.keys.sorted()[0]] ?? ""
+    }
+}
